def load() -> pd.DataFrame:
    with open('data/environment/input/constitution_beach_datasheet.csv', 'r', encoding='latin-1') as f:
        lines = [f.readline() for _ in range(20)]
    return pd.DataFrame({'line': lines})

def process(beach_data):
    df = beach_data.copy()
    df['Date_parsed'] = pd.to_datetime(df['Date'], errors='coerce')
    df_2024 = df[df['Date_parsed'].dt.year == 2024].copy()

    # Check each point against the 104 threshold (meets standard if < 104)
    df_2024['North_meets'] = df_2024['Entero_North'] < 104
    df_2024['Middle_meets'] = df_2024['Entero_Middle'] < 104
    df_2024['South_meets'] = df_2024['Entero_South'] < 104

    # Only consider points that have actual measurements (not NaN)
    # A day is "mixed" if among the non-null measurements, at least one meets and at least one does not
    def is_mixed(row):
        meets = []
        for col in ['North_meets', 'Middle_meets', 'South_meets']:
            entero_col = col.replace('_meets', '').replace('North', 'Entero_North').replace('Middle', 'Entero_Middle').replace('South', 'Entero_South')
        # Use the actual entero values to check for NaN
        vals = {
            'North': row['Entero_North'],
            'Middle': row['Entero_Middle'],
            'South': row['Entero_South'],
        }
        for key, v in vals.items():
            if pd.notna(v):
                meets.append(v < 104)
        if len(meets) == 0:
            return False
        return any(meets) and not all(meets)

    df_2024['mixed'] = df_2024.apply(is_mixed, axis=1)

    result = df_2024[['Date', 'Date_parsed', 'Entero_North', 'Entero_Middle', 'Entero_South',
                       'North_meets', 'Middle_meets', 'South_meets', 'mixed']]
    return result

def process(mixed_standard_days):
    # Show all mixed days for manual verification
    mixed = mixed_standard_days[mixed_standard_days['mixed'] == True][
        ['Date', 'Entero_North', 'Entero_Middle', 'Entero_South', 'North_meets', 'Middle_meets', 'South_meets']
    ].reset_index(drop=True)
    return mixed
